'use client';

import { useState, useEffect } from 'react';
import { useAuthStore } from '@/lib/store';
import API from '@/lib/api';
import { updateProfile } from '@/lib/profile';
import { toast } from 'react-toastify';
import { FaUser, FaEnvelope, FaLock, FaCamera, FaEye, FaEyeSlash, FaSave } from 'react-icons/fa';
import Image from 'next/image';
import { getErrorMessage } from '@/lib/errorHandler';

export default function AdminProfile() {
  const { user, setUser } = useAuthStore();
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(false);
  const [showCurrentPassword, setShowCurrentPassword] = useState(false);
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    profileImage: '',
  });

  const [passwordData, setPasswordData] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: '',
  });

  const [photoFile, setPhotoFile] = useState<File | null>(null);
  const [photoPreview, setPhotoPreview] = useState<string>('');

  const buildImageUrl = (path: string) => {
    const baseUrl = process.env.NEXT_PUBLIC_API_URL?.replace(/\/$/, '') || 'http://localhost:5000';
    return path.startsWith('http') ? path : `${baseUrl}/${path}`;
  };

  useEffect(() => {
    if (user) {
      setFormData({
        name: user.name || '',
        email: user.email || '',
        profileImage: user.profileImage || '',
      });
      if (user.profileImage) {
        setPhotoPreview(buildImageUrl(user.profileImage));
      }
    }
  }, [user]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value,
    }));
  };

  const handlePasswordChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setPasswordData(prev => ({
      ...prev,
      [name]: value,
    }));
  };

  const handlePhotoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setPhotoFile(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setPhotoPreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);

      const formDataToSend = new FormData();
      formDataToSend.append('name', formData.name);
      formDataToSend.append('email', formData.email);
      if (photoFile) {
        formDataToSend.append('profileImage', photoFile);
      }

      const updatedUser = await updateProfile(formDataToSend);
      setUser(updatedUser);
      if (updatedUser.profileImage) {
        const imageUrl = updatedUser.profileImage.startsWith('http')
          ? updatedUser.profileImage
          : `${process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000'}/${updatedUser.profileImage}`;
        setPhotoPreview(imageUrl);
      }
      toast.success('✅ Profile updated successfully!');
      setIsEditing(false);
      setPhotoFile(null);
    } catch (error: any) {
      toast.error(getErrorMessage(error, '❌ Unable to update profile. Please try again.'));
    } finally {
      setLoading(false);
    }
  };

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();

    if (passwordData.newPassword !== passwordData.confirmPassword) {
      toast.error('❌ New passwords do not match');
      return;
    }

    try {
      setLoading(true);

      await API.put('/users/password', {
        currentPassword: passwordData.currentPassword,
        newPassword: passwordData.newPassword,
      });

