'use client';

import { useState } from 'react';
import API from '@/lib/api';
import { toast } from 'react-toastify';
import Link from 'next/link';
import { getErrorMessage } from '@/lib/errorHandler';

export default function ForgotPassword() {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [emailSent, setEmailSent] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);
      console.log('Sending forgot password request for:', email);
      console.log('API endpoint:', '/auth/forgot-password');

      await API.post('/auth/forgot-password', { email });

      setEmailSent(true);
      toast.success('✅ Password reset email sent! Please check your inbox.');
    } catch (error: any) {
      console.error('Forgot password error:', {
        status: error.response?.status,
        statusText: error.response?.statusText,
        message: error.response?.data?.message,
        url: error.config?.url,
        baseURL: error.config?.baseURL,
        fullURL: `${error.config?.baseURL}${error.config?.url}`
      });

      toast.error(getErrorMessage(error, '❌ Unable to send reset email. Please try again.'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container max-w-md py-12">
      <div className="card bg-white">
        <h2 className="text-2xl font-bold mb-6 text-center">Forgot Password</h2>

        {emailSent ? (
          <div className="p-4 bg-green-50 border border-green-200 rounded-lg text-center">
            <p className="text-green-800 mb-4">
              Check your email for password reset instructions. The link will expire in 30 minutes.
            </p>
            <Link href="/login" className="btn-primary">
              Back to Login
            </Link>
          </div>
        ) : (
          <form onSubmit={handleSubmit}>
            <div className="mb-6">
              <label className="block text-sm font-semibold mb-2">Email Address</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                className="input-field"
                placeholder="your@email.com"
              />
              <p className="text-sm text-gray-600 mt-2">
                Enter your registered email and we&apos;ll send you a link to reset your password
              </p>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="btn-primary w-full mb-4"
            >
              {loading ? 'Sending...' : 'Send Reset Link'}
            </button>
          </form>
        )}

        <div className="text-center text-sm text-gray-600">
          <Link href="/login" className="text-primary font-semibold hover:underline">
            Back to Login
          </Link>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import API from '@/lib/api';
import { AxiosError } from 'axios';

interface FetchState<T> {
  data: T | null;
  loading: boolean;
  error: string | null;
}

interface FetchOptions {
  immediate?: boolean;
}

/**
 * Custom hook for fetching data from API
 * Provides loading, error states and refetch functionality
 * @template T - Type of data to be fetched
 * @param {string} url - API endpoint URL
 * @param {FetchOptions} options - Fetch options
 * @returns {Object} Fetch state and refetch function
 */
export function useFetch<T>(url: string, options: FetchOptions = { immediate: true }) {
  const [state, setState] = useState<FetchState<T>>({
    data: null,
    loading: options.immediate ?? true,
    error: null,
  });

  const fetchData = async () => {
    setState(prev => ({ ...prev, loading: true, error: null }));

    try {
      const response = await API.get(url);
      setState({
        data: response.data,
        loading: false,
        error: null,
      });
    } catch (err) {
      const error = err as AxiosError<{ message: string }>;
      setState({
        data: null,
        loading: false,
        error: error.response?.data?.message || 'An error occurred',
      });
    }
  };

  useEffect(() => {
    if (options.immediate) {
      fetchData();
    }
  }, [url]);

  return {
    ...state,
    refetch: fetchData,
  };
}

/**
 * Custom hook for POST/PUT/DELETE operations
 * Provides loading and error states for mutations
 * @template T - Type of request data
 * @template R - Type of response data
 * @returns {Object} Mutation state and execute function
 */
export function useMutation<T = any, R = any>() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const execute = async (
    method: 'post' | 'put' | 'delete',
    url: string,
    data?: T
  ): Promise<R | null> => {
    setLoading(true);
    setError(null);

    try {
      const response = await API[method](url, data as any);
      setLoading(false);
      return response.data;
    } catch (err) {
      const error = err as AxiosError<{ message: string }>;
      const errorMessage = error.response?.data?.message || 'An error occurred';
      setError(errorMessage);
      setLoading(false);
      return null;
    }
  };

  return {
    loading,
    error,
    execute,
  };
}

import { useState, useCallback } from 'react';

interface FormState<T> {
  values: T;
  errors: Partial<Record<keyof T, string>>;
  touched: Partial<Record<keyof T, boolean>>;
}

interface UseFormOptions<T> {
  initialValues: T;
  validate?: (values: T) => Partial<Record<keyof T, string>>;
  onSubmit: (values: T) => void | Promise<void>;
}

/**
 * Custom hook for form handling with validation
 * Provides form state management and validation
 * @template T - Type of form values
 * @param {UseFormOptions<T>} options - Form configuration
 * @returns {Object} Form state and handlers
 */
export function useForm<T extends Record<string, any>>({
  initialValues,
  validate,
  onSubmit,
}: UseFormOptions<T>) {
  const [state, setState] = useState<FormState<T>>({
    values: initialValues,
    errors: {},
    touched: {},
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  /**
   * Handle input change
   */
  const handleChange = useCallback((name: keyof T, value: any) => {
    setState(prev => ({
      ...prev,
      values: {
        ...prev.values,
        [name]: value,
      },
    }));
  }, []);

  /**
   * Handle input blur
   */
  const handleBlur = useCallback((name: keyof T) => {
    setState(prev => ({
      ...prev,
      touched: {
        ...prev.touched,
        [name]: true,
      },
    }));

    if (validate) {
      const errors = validate(state.values);
      setState(prev => ({
        ...prev,
        errors,
      }));
    }
  }, [validate, state.values]);

  /**
   * Handle form submit
   */
  const handleSubmit = useCallback(async (e?: React.FormEvent) => {
    if (e) {
      e.preventDefault();
    }

    // Mark all fields as touched
    const allTouched = Object.keys(state.values).reduce((acc, key) => ({
      ...acc,
      [key]: true,
    }), {});

    setState(prev => ({
      ...prev,
      touched: allTouched,
    }));

    // Validate
    if (validate) {
      const errors = validate(state.values);
      setState(prev => ({
        ...prev,
        errors,
      }));

      if (Object.keys(errors).length > 0) {
        return;
      }
    }

    // Submit
    setIsSubmitting(true);
    try {
      await onSubmit(state.values);
    } finally {
      setIsSubmitting(false);
    }
  }, [state.values, validate, onSubmit]);

  /**
   * Reset form to initial values
   */
  const reset = useCallback(() => {
    setState({
      values: initialValues,
      errors: {},
      touched: {},
    });
  }, [initialValues]);

  /**
   * Set form values programmatically
   */
  const setValues = useCallback((values: Partial<T>) => {
    setState(prev => ({
      ...prev,
      values: {
        ...prev.values,
        ...values,
      },
    }));
  }, []);

  return {
    values: state.values,
    errors: state.errors,
    touched: state.touched,
    isSubmitting,
    handleChange,
    handleBlur,
    handleSubmit,
    reset,
    setValues,
  };
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import API from '@/lib/api';
import { useAuthStore } from '@/lib/store';
import { toast } from 'react-toastify';
import Link from 'next/link';
import { FaEnvelope, FaLock, FaSignInAlt, FaUserShield, FaUser, FaEye, FaEyeSlash } from 'react-icons/fa';
import { getErrorMessage } from '@/lib/errorHandler';

export default function Login() {
  const router = useRouter();
  const { setUser, setToken, isAuthenticated, user } = useAuthStore();
  const [formData, setFormData] = useState({
    email: '',
    password: '',
  });
  const [loading, setLoading] = useState(false);
  const [loginType, setLoginType] = useState<'user' | 'admin'>('user');
  const [showPassword, setShowPassword] = useState(false);
  const [mounted, setMounted] = useState(false);

  // Handle client-side mounting
  useEffect(() => {
    setMounted(true);
  }, []);

  // Redirect if already logged in
  useEffect(() => {
    if (mounted && isAuthenticated && user) {
      if (user.role === 'admin') {
        router.replace('/admin/dashboard');
      } else {
        router.replace('/');
      }
    }
  }, [mounted, isAuthenticated, user, router]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Prevent multiple submissions
    if (loading) return;

    try {
      setLoading(true);

      console.log('Attempting login with:', { email: formData.email });

      const response = await API.post('/auth/login', formData);

      console.log('Login successful:', response.data);

      const token = response.data?.token || null;
      const userData = response.data?.data?.user || response.data?.user || null;

      if (token) {
        setToken(token);
      }
      if (userData) {
        setUser(userData);
      }

      toast.success('🎉 Login successful!');

      // Use replace instead of push to prevent back button issues
      if (response.data.user.role === 'admin') {
        router.replace('/admin/dashboard');
      } else {
        router.replace('/');
      }
    } catch (error: any) {
      console.error('Login error details:', {
        status: error.response?.status,
        message: error.response?.data?.message,
        error: error.message,
        credentials: { email: formData.email } // Don't log password
      });

      // More specific error message for 401
      let errorMessage;
      if (error.response?.status === 401) {
        errorMessage = '❌ Invalid email or password. Please check your credentials or register a new account.';
      } else {
        errorMessage = getErrorMessage(error, '❌ Unable to log in. Please try again.');
      }

      toast.error(errorMessage, {
        position: 'top-right',
        autoClose: 5000,
        hideProgressBar: false,
        closeOnClick: true,
        pauseOnHover: true,
      });
      setLoading(false);
    }
  };

  // Don't render login form if already authenticated
  if (!mounted || (isAuthenticated && user)) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 via-primary/20 to-gray-900 flex items-center justify-center">
        <div className="text-white text-xl">Loading...</div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-primary/20 to-gray-900 flex items-center justify-center py-12 px-4">
      {/* Background Decoration */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-20 left-10 w-72 h-72 bg-primary/20 rounded-full blur-3xl"></div>
        <div className="absolute bottom-20 right-10 w-96 h-96 bg-red-600/10 rounded-full blur-3xl"></div>
      </div>

      <div className="relative w-full max-w-md z-10 animate-slideInUp">
        {/* Card Container */}
        <div className="bg-white rounded-2xl shadow-2xl overflow-hidden">
          {/* Header Gradient */}
          <div className="bg-gradient-to-r from-primary to-red-600 p-8 text-center">
            <div className="text-5xl mb-3">🍽️</div>
            <h1 className="text-3xl font-black text-white mb-2">Jhasha</h1>
            <p className="text-white/90">Welcome Back</p>
          </div>

          {/* Form Section */}
          <div className="p-8">
            {/* Login Type Toggle */}
            <div className="mb-8">
              <div className="flex bg-gray-100 p-1 rounded-lg">
                <button
                  type="button"
                  onClick={() => setLoginType('user')}
                  className={
                    `flex-1 py-2 px-4 rounded-md font-bold text-sm transition flex items-center justify-center gap-2 ` +
                    (loginType === 'user'
                      ? 'bg-gradient-to-r from-primary to-red-600 text-white shadow-md'
                      : 'text-gray-600 hover:text-gray-900')
                  }
                >
                  <FaUser /> Customer Login
                </button>
                <button
                  type="button"
                  onClick={() => setLoginType('admin')}
                  className={
                    `flex-1 py-2 px-4 rounded-md font-bold text-sm transition flex items-center justify-center gap-2 ` +
                    (loginType === 'admin'
                      ? 'bg-gradient-to-r from-primary to-red-600 text-white shadow-md'
                      : 'text-gray-600 hover:text-gray-900')
                  }
                >
                  <FaUserShield /> Admin Login
                </button>
              </div>
            </div>

            <p className="text-center text-gray-600 mb-8 text-sm">
              {loginType === 'admin' ? '🔐 Admin Portal Access' : 'Sign in to order your favorite dishes'}
            </p>

            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Email Field */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-3">Email Address</label>
                <div className="relative">
                  <FaEnvelope className="absolute left-4 top-4 text-primary text-lg" />
                  <input
                    type="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    required
                    className="w-full pl-12 pr-4 py-3 rounded-lg border-2 border-gray-200 focus:border-primary focus:outline-none transition bg-gray-50 focus:bg-white"
                    placeholder="you@example.com"
                  />
                </div>
              </div>

              {/* Password Field */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-3">Password</label>
                <div className="relative">
                  <FaLock className="absolute left-4 top-4 text-primary text-lg" />
                  <input
                    type={showPassword ? 'text' : 'password'}
                    name="password"
                    value={formData.password}
                    onChange={handleChange}
                    required
                    className="w-full pl-12 pr-12 py-3 rounded-lg border-2 border-gray-200 focus:border-primary focus:outline-none transition bg-gray-50 focus:bg-white"
                    placeholder="••••••••"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-4 top-4 text-primary text-lg hover:text-red-600 transition"
                  >
                    {showPassword ? <FaEyeSlash /> : <FaEye />}
                  </button>
                </div>
              </div>

              {/* Remember Me & Forgot Password */}
              <div className="flex items-center justify-between text-sm">
                <label className="flex items-center gap-2 cursor-pointer">
                  <input type="checkbox" className="w-4 h-4 rounded border-gray-300" />
                  <span className="text-gray-700">Remember me</span>
                </label>
                {loginType === 'user' && (
                  <Link href="/forgot-password" className="text-primary font-semibold hover:text-red-600 transition">
                    Forgot?
                  </Link>
                )}
              </div>

              {/* Submit Button */}
              <button
                type="submit"
                disabled={loading}
