'use client';

import { useEffect, useState } from 'react';
import API from '@/lib/api';
import FoodCard from '@/components/FoodCard';
import type { FoodItem } from '@/lib/types';
import { toast } from 'react-toastify';
import { FaSearch, FaFire } from 'react-icons/fa';

export default function Home() {
  const [foods, setFoods] = useState<FoodItem[]>([]);
  const [categories, setCategories] = useState<{ id: string; label: string; emoji: string }[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchCategories();
  }, []);

  useEffect(() => {
    fetchFoods();
  }, [selectedCategory, searchTerm]);

  const fetchCategories = async () => {
    try {
      const response = await API.get('/categories');
      const categoryList = response.data?.data?.categories ?? [];
      const mappedCategories = categoryList.map((category: { name: string; slug?: string }) => ({
        id: category.slug || category.name.toLowerCase().replace(/\s+/g, '-'),
        label: category.name,
        emoji: '🍽️',
      }));
      setCategories(mappedCategories);
    } catch (error) {
      setCategories([
        { id: 'starter', label: '🥘 Starter', emoji: '🥘' },
        { id: 'main_course', label: '🍛 Main Course', emoji: '🍛' },
        { id: 'dessert', label: '🍰 Dessert', emoji: '🍰' },
        { id: 'beverage', label: '🥤 Beverage', emoji: '🥤' },
        { id: 'side_dish', label: '🥗 Side Dish', emoji: '🥗' },
      ]);
    }
  };

  const fetchFoods = async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams();
      if (selectedCategory) params.append('category', selectedCategory);
      if (searchTerm) params.append('search', searchTerm);

      const response = await API.get(`/products?${params.toString()}`);
      const products = response.data?.data?.products ?? [];
      setFoods(products);
    } catch (error) {
      toast.error('Failed to fetch foods');
    } finally {
      setLoading(false);
    }
  };

  const _categoryEmojis: { [key: string]: string } = {
    starter: '🥘',
    main_course: '🍛',
    dessert: '🍰',
    beverage: '🥤',
    side_dish: '🥗',
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-50 to-white">
      {/* Hero Section */}
      <div className="bg-gradient-to-r from-primary via-red-600 to-orange-500 text-white pt-16 pb-12 mb-12 relative overflow-hidden">
        <div className="absolute inset-0 opacity-10">
          <div className="absolute top-4 left-10 text-6xl animate-pulse">🍽️</div>
          <div className="absolute top-20 right-20 text-5xl animate-bounce">🍔</div>
          <div className="absolute bottom-4 left-1/3 text-5xl animate-pulse">🌮</div>
        </div>
        <div className="container relative z-10">
          <h1 className="text-5xl md:text-6xl font-black mb-3 leading-tight animate-slideInUp">
            Welcome to <span className="text-yellow-300">Jhasha</span> Restaurant
          </h1>
          <p className="text-xl md:text-2xl mb-6 opacity-95 animate-slideInUp" style={{ animationDelay: '0.1s' }}>
            🚀 Experience authentic flavors delivered to your doorstep
          </p>
          <div className="flex flex-wrap gap-4 text-sm animate-slideInUp" style={{ animationDelay: '0.2s' }}>
            <span className="bg-white/20 px-4 py-2 rounded-full">⚡ Fast Delivery</span>
            <span className="bg-white/20 px-4 py-2 rounded-full">🔥 Hot & Fresh</span>
            <span className="bg-white/20 px-4 py-2 rounded-full">⭐ Quality Assured</span>
          </div>
        </div>
      </div>

      <div className="container">
        {/* Search Bar */}
        <div className="mb-8 relative animate-slideInUp" style={{ animationDelay: '0.3s' }}>
          <div className="relative">
            <FaSearch className="absolute left-4 top-4 text-gray-400 text-lg" />
            <input
              type="text"
              placeholder="Search for your favorite dishes..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-12 pr-4 py-3 rounded-xl border-2 border-gray-200 focus:border-primary focus:outline-none transition text-lg shadow-sm"
            />
          </div>
        </div>

        {/* Category Filter */}
        <div className="mb-10 animate-slideInUp" style={{ animationDelay: '0.4s' }}>
          <h2 className="section-title mb-4 flex items-center gap-2">
            <FaFire className="text-primary" /> Filter by Category
          </h2>
          <div className="flex flex-wrap gap-3">
            <button
              onClick={() => setSelectedCategory('')}
              className={`px-5 py-2 rounded-full font-semibold transition transform hover:scale-105 ${
                selectedCategory === ''
                  ? 'bg-gradient-to-r from-primary to-red-600 text-white shadow-lg'
                  : 'bg-white border-2 border-gray-200 text-gray-700 hover:border-primary'
              }`}
            >
              🍽️ All
            </button>
            {categories.map((cat) => (
              <button
                key={cat.id}
                onClick={() => setSelectedCategory(cat.id)}
                className={`px-5 py-2 rounded-full font-semibold transition transform hover:scale-105 ${
                  selectedCategory === cat.id
                    ? 'bg-gradient-to-r from-primary to-red-600 text-white shadow-lg'
                    : 'bg-white border-2 border-gray-200 text-gray-700 hover:border-primary'
                }`}
              >
                {cat.label}
              </button>
            ))}
          </div>
        </div>

        {/* Food Grid */}
        {loading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-12">
            {[1, 2, 3, 4, 5, 6].map((i) => (
              <div key={i} className="card h-96 bg-gray-200 animate-pulse rounded-xl"></div>
            ))}
          </div>
        ) : foods.length === 0 ? (
          <div className="text-center py-16">
            <div className="text-6xl mb-4">😔</div>
            <p className="text-xl text-gray-600">No dishes found. Try a different search!</p>
          </div>
        ) : (
          <div>
            <h2 className="section-title mb-8">
              🔥 {foods.length} Delicious Option{foods.length !== 1 ? 's' : ''} Available
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mb-12">
              {foods.map((food, index) => (
                <div key={food._id} style={{ animationDelay: `${index * 0.1}s` }} className="animate-slideInUp">
                  <FoodCard food={food} />
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useAuthStore } from '@/lib/store';
import { toast } from 'react-toastify';
import { useRouter } from 'next/navigation';
import { FaCamera, FaUser, FaPhone, FaMapMarkerAlt, FaCity, FaMailBulk, FaEdit } from 'react-icons/fa';
import { getErrorMessage } from '@/lib/errorHandler';
import { getCurrentUser, updateProfile, changePassword, setup2FA, enable2FA, disable2FA } from '@/lib/profile';

export default function Profile() {
  const router = useRouter();
  const { isAuthenticated, user, setUser } = useAuthStore();
  const [mounted, setMounted] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    address: '',
    city: '',
    zipCode: '',
  });
  const [profileImage, setProfileImage] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);
  const [imagePreview, setImagePreview] = useState<string>('');
  const [isEditing, setIsEditing] = useState(false);
  const [passwordData, setPasswordData] = useState({ currentPassword: '', newPassword: '', confirmPassword: '' });
  const [twoFAStatus, setTwoFAStatus] = useState({ enabled: user?.twoFactorEnabled || false, secret: '', qrCodeUrl: '', token: '' });
  const [_passwordLoading, setPasswordLoading] = useState(false);

  const buildImageUrl = (path: string) => {
    const baseUrl = process.env.NEXT_PUBLIC_API_URL?.replace(/\/$/, '') || 'http://localhost:5000';
    return path.startsWith('http') ? path : `${baseUrl}/${path}`;
  };

  const fetchProfile = async () => {
    try {
      const userData = await getCurrentUser();
      setFormData({
        name: userData.name,
        phone: userData.phone || '',
        address: userData.address || '',
        city: userData.city || '',
        zipCode: userData.zipCode || '',
      });
      if (userData.profileImage) {
        setImagePreview(buildImageUrl(userData.profileImage));
      }
      setUser(userData as any);
    } catch (error: any) {
      toast.error(getErrorMessage(error, '⚠️ Unable to load your profile. Please refresh the page.'));
    }
  };

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!mounted) return;

    if (!isAuthenticated) {
      router.push('/login');
      return;
    }

    if (user) {
      setFormData({
        name: user.name,
        phone: user.phone || '',
        address: user.address || '',
        city: user.city || '',
        zipCode: user.zipCode || '',
      });

      setTwoFAStatus((prev) => ({
        ...prev,
        enabled: user.twoFactorEnabled || false,
      }));

      if (user.profileImage) {
        setImagePreview(buildImageUrl(user.profileImage));
      }
    }

    fetchProfile();
  }, [mounted, isAuthenticated, router, user]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setProfileImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const _handlePasswordSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passwordData.newPassword !== passwordData.confirmPassword) {
      toast.error('❌ New passwords do not match');
      return;
    }

    try {
      setPasswordLoading(true);
      await changePassword(passwordData.currentPassword, passwordData.newPassword);
      toast.success('✅ Password updated successfully!');
      setPasswordData({ currentPassword: '', newPassword: '', confirmPassword: '' });
    } catch (error: any) {
      toast.error(getErrorMessage(error, '❌ Unable to update your password. Please try again.'));
    } finally {
      setPasswordLoading(false);
    }
  };

  const _handle2FASetup = async () => {
    try {
      const result = await setup2FA();
      setTwoFAStatus((prev) => ({ ...prev, secret: result.secret, qrCodeUrl: result.qrCodeUrl }));
    } catch (error: any) {
      toast.error(getErrorMessage(error, '❌ Unable to start 2FA setup. Please try again.'));
    }
  };

  const _handle2FAEnable = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await enable2FA(twoFAStatus.token);
      setTwoFAStatus((prev) => ({ ...prev, enabled: true, token: '' }));
      setUser(user ? { ...user, twoFactorEnabled: true } : null);
      toast.success('✅ Two-factor authentication enabled!');
    } catch (error: any) {
      toast.error(getErrorMessage(error, '❌ Unable to enable 2FA. Please check the token and try again.'));
    }
  };

  const _handle2FADisable = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await disable2FA(passwordData.currentPassword);
      setTwoFAStatus((prev) => ({ ...prev, enabled: false, token: '' }));
      setUser(user ? { ...user, twoFactorEnabled: false } : null);
      toast.success('✅ Two-factor authentication disabled!');
      setPasswordData((prev) => ({ ...prev, currentPassword: '' }));
    } catch (error: any) {
      toast.error(getErrorMessage(error, '❌ Unable to disable 2FA. Please check your password and try again.'));
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setLoading(true);

      const formDataToSend = new FormData();
      formDataToSend.append('name', formData.name);
      formDataToSend.append('phone', formData.phone);
      formDataToSend.append('address', formData.address);
      formDataToSend.append('city', formData.city);
      formDataToSend.append('zipCode', formData.zipCode);

      if (profileImage) {
        formDataToSend.append('profileImage', profileImage);
      }

      const updatedUser = await updateProfile(formDataToSend);
      setUser(updatedUser as any);

      if (updatedUser.profileImage) {
        setImagePreview(buildImageUrl(updatedUser.profileImage));
      }

      setProfileImage(null);
      toast.success('✅ Profile updated successfully!');
      setIsEditing(false);
    } catch (error: any) {
      toast.error(getErrorMessage(error, '❌ Unable to update your profile. Please try again.'));
    } finally {
      setLoading(false);
    }
  };

  // Prevent hydration mismatch
  if (!mounted) {
    return null;
  }

  if (!isAuthenticated) {
    return null;
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-50 to-white py-12">
      <div className="container max-w-4xl">
        {/* Header */}
        <div className="mb-8 animate-slideInUp">
          <h1 className="text-4xl font-black text-gray-900 flex items-center gap-3 mb-2">
            <FaUser className="text-primary" /> My Profile
          </h1>
          <p className="text-gray-600">Manage your account information</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Profile Card */}
          <div className="lg:col-span-2 animate-slideInUp">
            <div className="card bg-white">
              <form onSubmit={handleSubmit}>
                {/* Profile Image Section */}
                <div className="mb-8 text-center pb-8 border-b-2 border-gray-200">
                  <div className="relative w-40 h-40 mx-auto mb-4">
                    <div className="w-full h-full rounded-full bg-gradient-to-br from-gray-100 to-gray-200 overflow-hidden flex items-center justify-center border-4 border-primary/20">
                      {imagePreview ? (
                        <img
                          key={imagePreview}
                          src={`${imagePreview}?t=${Date.now()}`}
                          alt="Profile"
                          className="w-full h-full object-cover"
                        />
                      ) : (
                        <div className="text-6xl">👤</div>
                      )}
                    </div>
                    <label className="absolute bottom-0 right-0 bg-gradient-to-r from-primary to-red-600 text-white p-3 rounded-full cursor-pointer hover:shadow-lg transition transform hover:scale-110">
                      <input
                        type="file"
                        accept="image/*"
                        onChange={handleImageChange}
                        className="hidden"
                      />
                      <FaCamera size={20} />
                    </label>
                  </div>
                  <h2 className="text-2xl font-black text-gray-900 mb-1">{formData.name}</h2>
                  <p className="text-gray-600 mb-3 flex items-center justify-center gap-2">
                    <FaMailBulk className="text-primary" /> {user?.email}
                  </p>
                  {!isEditing && (
                    <button
                      type="button"
                      onClick={() => setIsEditing(true)}
                      className="inline-flex items-center gap-2 text-primary font-semibold hover:text-red-600 transition"
                    >
                      <FaEdit /> Edit Profile
                    </button>
                  )}
                </div>

                {/* Form Fields */}
                {isEditing && (
                  <>
                    <h3 className="text-xl font-bold text-gray-900 mb-6">Personal Information</h3>

                    <div className="space-y-6 mb-8">
                      {/* Name */}
                      <div>
                        <label className="block text-sm font-bold text-gray-700 mb-3">Full Name</label>
                        <div className="relative">
                          <FaUser className="absolute left-4 top-4 text-primary text-lg" />
                          <input
                            type="text"
                            name="name"
                            value={formData.name}
                            onChange={handleChange}
                            required
                            className="w-full pl-12 pr-4 py-3 rounded-lg border-2 border-gray-200 focus:border-primary focus:outline-none transition bg-gray-50 focus:bg-white"
                          />
                        </div>
                      </div>

                      {/* Phone */}
                      <div>
                        <label className="block text-sm font-bold text-gray-700 mb-3">Phone Number</label>
                        <div className="relative">
                          <FaPhone className="absolute left-4 top-4 text-primary text-lg" />
                          <input
                            type="tel"
                            name="phone"
                            value={formData.phone}
                            onChange={handleChange}
                            required
                            className="w-full pl-12 pr-4 py-3 rounded-lg border-2 border-gray-200 focus:border-primary focus:outline-none transition bg-gray-50 focus:bg-white"
                          />
                        </div>
                      </div>

                      {/* Address */}
                      <div>
                        <label className="block text-sm font-bold text-gray-700 mb-3">Street Address</label>
                        <div className="relative">
                          <FaMapMarkerAlt className="absolute left-4 top-4 text-primary text-lg" />
                          <input
                            type="text"
                            name="address"
                            value={formData.address}
                            onChange={handleChange}
                            className="w-full pl-12 pr-4 py-3 rounded-lg border-2 border-gray-200 focus:border-primary focus:outline-none transition bg-gray-50 focus:bg-white"
                            placeholder="123 Main Street"
                          />
                        </div>
                      </div>

                      {/* City and Zip Code */}
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                          <label className="block text-sm font-bold text-gray-700 mb-3">City</label>
                          <div className="relative">
                            <FaCity className="absolute left-4 top-4 text-primary text-lg" />
                            <input
                              type="text"
                              name="city"
                              value={formData.city}
                              onChange={handleChange}
                              className="w-full pl-12 pr-4 py-3 rounded-lg border-2 border-gray-200 focus:border-primary focus:outline-none transition bg-gray-50 focus:bg-white"
                              placeholder="New York"
                            />
                          </div>
                        </div>

                        <div>
                          <label className="block text-sm font-bold text-gray-700 mb-3">Zip Code</label>
                          <input
                            type="text"
                            name="zipCode"
                            value={formData.zipCode}
                            onChange={handleChange}
                            className="w-full px-4 py-3 rounded-lg border-2 border-gray-200 focus:border-primary focus:outline-none transition bg-gray-50 focus:bg-white"
                            placeholder="10001"
                          />
                        </div>
                      </div>
                    </div>

                    {/* Action Buttons */}
                    <div className="flex gap-3">
                      <button
                        type="submit"
                        disabled={loading}
                        className="flex-1 bg-gradient-to-r from-primary to-red-600 hover:from-primary/90 hover:to-red-600/90 text-white font-bold py-3 rounded-lg transition transform hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        {loading ? '⏳ Updating...' : '✅ Save Changes'}
                      </button>
                      <button
                        type="button"
                        onClick={() => {
                          setIsEditing(false);
                          fetchProfile();
                        }}
                        className="flex-1 border-2 border-gray-300 text-gray-700 font-bold py-3 rounded-lg hover:border-primary hover:text-primary transition"
                      >
                        Cancel
                      </button>
                    </div>
