                    {new Date(user?.createdAt || '').toLocaleDateString()}
                  </p>
                </div>
              </div>

              {/* Security Note */}
              <div className="mt-6 bg-yellow-50 border-2 border-yellow-200 rounded-lg p-3">
                <p className="text-xs font-bold text-yellow-800">🔒 Security Tip</p>
