'use client';

import { useParams } from 'next/navigation';
import { useState } from 'react';
import API from '@/lib/api';
import { toast } from 'react-toastify';
import { useRouter } from 'next/navigation';
import { getErrorMessage } from '@/lib/errorHandler';

export default function ResetPassword() {
  const params = useParams();
  const router = useRouter();
  const resetToken = (params?.token as string) || '';
  const [formData, setFormData] = useState({
    newPassword: '',
    confirmPassword: '',
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (formData.newPassword !== formData.confirmPassword) {
      toast.error('Passwords do not match');
      return;
    }

    try {
      setLoading(true);
      await API.post('/auth/reset-password', {
        resetToken,
        password: formData.newPassword,
      });
      toast.success('Password reset successful!');
      router.push('/login');
    } catch (error: any) {
      toast.error(getErrorMessage(error, '❌ Unable to reset password. The link may have expired.'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container max-w-md py-12">
      <div className="card bg-white">
        <h2 className="text-2xl font-bold mb-6 text-center">Reset Password</h2>

        <form onSubmit={handleSubmit}>
          <div className="mb-4">
            <label className="block text-sm font-semibold mb-2">New Password</label>
            <input
              type="password"
              name="newPassword"
              value={formData.newPassword}
              onChange={handleChange}
              required
              className="input-field"
              placeholder="••••••••"
            />
          </div>

          <div className="mb-6">
            <label className="block text-sm font-semibold mb-2">Confirm Password</label>
            <input
              type="password"
              name="confirmPassword"
              value={formData.confirmPassword}
              onChange={handleChange}
              required
              className="input-field"
              placeholder="••••••••"
            />
          </div>

          <button
            type="submit"
            disabled={loading}
            className="btn-primary w-full"
          >
            {loading ? 'Resetting...' : 'Reset Password'}
          </button>
        </form>
      </div>
    </div>
  );
}

'use client';

import { useState, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import Link from 'next/link';
import API from '@/lib/api';
import { toast } from 'react-toastify';
import { FaLock, FaArrowLeft, FaEye, FaEyeSlash, FaCheckCircle } from 'react-icons/fa';
import { getErrorMessage } from '@/lib/errorHandler';

function ResetPasswordContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const token = searchParams?.get('token') || null;

  const [formData, setFormData] = useState({
    newPassword: '',
    confirmPassword: '',
  });
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [resetSuccess, setResetSuccess] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!token) {
      toast.error('❌ Invalid reset link');
      return;
    }

    if (formData.newPassword !== formData.confirmPassword) {
      toast.error('❌ Passwords do not match');
      return;
    }

    if (formData.newPassword.length < 6) {
      toast.error('❌ Password must be at least 6 characters');
      return;
    }

    try {
      setLoading(true);
      await API.post('/auth/reset-password', {
        resetToken: token,
        password: formData.newPassword,
      });

      setResetSuccess(true);
      toast.success('✅ Password reset successful!');

      // Redirect to login after 3 seconds
      setTimeout(() => {
        router.push('/login');
      }, 3000);
    } catch (error: any) {
      toast.error(getErrorMessage(error, '❌ Unable to reset password. Please try again.'));
    } finally {
      setLoading(false);
    }
  };

  if (!token) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-gray-50 to-white flex items-center justify-center py-12 px-4">
        <div className="max-w-md w-full animate-slideInUp">
